Here is the root cause:
The `kaweth_set_rx_mode()` function (the `ndo_set_rx_mode` callback) incorrectly calls `netif_stop_queue()` and `netif_wake_queue()`, which are TX queue flow control functions unrelated to RX configuration. The premature `netif_wake_queue()` can re-enable the TX queue while `tx_urb` is still in-flight, allowing `kaweth_start_xmit()` to submit the same URB again while active, triggering a WARN in `usb_submit_urb()` ("URB submitted while active").

Here is the patch:
  ****************************************************************/
 static void kaweth_set_rx_mode(struct net_device *net)
 {
 	struct kaweth_device *kaweth = netdev_priv(net);

 	__u16 packet_filter_bitmap = KAWETH_PACKET_FILTER_DIRECTED |
                                      KAWETH_PACKET_FILTER_BROADCAST |
 		                     KAWETH_PACKET_FILTER_MULTICAST;

 	netdev_dbg(net, "Setting Rx mode to %d\n", packet_filter_bitmap);

-	netif_stop_queue(net);

 	if (net->flags & IFF_PROMISC) {
 		packet_filter_bitmap |= KAWETH_PACKET_FILTER_PROMISCUOUS;
 	}
 	else if (!netdev_mc_empty(net) || (net->flags & IFF_ALLMULTI)) {
 		packet_filter_bitmap |= KAWETH_PACKET_FILTER_ALL_MULTICAST;
 	}

 	kaweth->packet_filter_bitmap = packet_filter_bitmap;
-	netif_wake_queue(net);
 }



